#define Q_PROPERTY_CREATE(TYPE, M)                          \
    Q_PROPERTY(TYPE p##M MEMBER _p##M NOTIFY p##M##Changed) \
public:                                                     \
    Q_SIGNAL void p##M##Changed();                          \
    void set##M(TYPE M)                                     \
    {                                                       \
        _p##M = M;                                          \
        Q_EMIT p##M##Changed();                             \
    }                                                       \
    Q_REQUIRED_RESULT TYPE get##M() const                   \
    {                                                       \
        return _p##M;                                       \
    }                                                       \
                                                            \
private:                                                    \
    TYPE _p##M{};
#define Q_PROPERTY_REF_CREATE(TYPE, M)                      \
    Q_PROPERTY(TYPE p##M MEMBER _p##M NOTIFY p##M##Changed) \
public:                                                     \
    Q_SIGNAL void p##M##Changed();                          \
    void set##M(const TYPE& M)                              \
    {                                                       \
        _p##M = M;                                          \
        Q_EMIT p##M##Changed();                             \
    }                                                       \
    Q_REQUIRED_RESULT const TYPE& get##M() const            \
    {                                                       \
        return _p##M;                                       \
    }                                                       \
                                                            \
private:                                                    \
    TYPE _p##M{};
#define Q_PROPERTY_CREATE_Q_H(TYPE, M)                                  \
    Q_PROPERTY(TYPE p##M READ get##M WRITE set##M NOTIFY p##M##Changed) \
public:                                                                 \
    Q_SIGNAL void p##M##Changed();                                      \
    void set##M(TYPE M);                                                \
    Q_REQUIRED_RESULT TYPE get##M() const;
#define Q_PROPERTY_REF_CREATE_Q_H(TYPE, M)                              \
    Q_PROPERTY(TYPE p##M READ get##M WRITE set##M NOTIFY p##M##Changed) \
public:                                                                 \
    Q_SIGNAL void p##M##Changed();                                      \
    void set##M(const TYPE& M);                                         \
    Q_REQUIRED_RESULT const TYPE& get##M() const;
#define Q_PROPERTY_CREATE_D(TYPE, M) \
private:                             \
    TYPE _p##M{};
#define Q_PRIVATE_CREATE_D(TYPE, M) \
private:                            \
    TYPE _p##M{};
#define Q_PRIVATE_CREATE(TYPE, M)         \
public:                                   \
    void set##M(TYPE M)                   \
    {                                     \
        _p##M = M;                        \
    }                                     \
    Q_REQUIRED_RESULT TYPE get##M() const \
    {                                     \
        return _p##M;                     \
    }                                     \
                                          \
private:                                  \
    TYPE _p##M{};
#define Q_PRIVATE_REF_CREATE(TYPE, M)            \
public:                                          \
    void set##M(const TYPE& M)                   \
    {                                            \
        _p##M = M;                               \
    }                                            \
    Q_REQUIRED_RESULT const TYPE& get##M() const \
    {                                            \
        return _p##M;                            \
    }                                            \
                                                 \
private:                                         \
    TYPE _p##M{};
#define ELA_EXPORT
#define ElaDefVersion "2.0.3"

namespace ElaInternal
{
    // Qt containers use qsizetype while item models and many widget APIs use int.
    // Clamp at that API boundary instead of relying on an implementation-defined
    // narrowing conversion for unusually large containers.
    [[nodiscard]] constexpr int toInt(qint64 value) noexcept
    {
        constexpr auto intMin = static_cast<qint64>(std::numeric_limits<int>::min());
        constexpr auto intMax = static_cast<qint64>(std::numeric_limits<int>::max());
        return value < intMin ? std::numeric_limits<int>::min() : (value > intMax ? std::numeric_limits<int>::max() : static_cast<int>(value));
    }
}

