// ==== ElaStatusBarStyle ===================================================
class ElaStatusBarStyle : public QProxyStyle
{
    Q_OBJECT;

public:
    explicit ElaStatusBarStyle(QStyle* style = nullptr)
    {
        _themeMode = eTheme->getThemeMode();
        connect(
            eTheme,
            &ElaTheme::themeModeChanged,
            this,
            [=](ElaThemeType::ThemeMode themeMode) {
                _themeMode = themeMode;
            }
        );
    }

    ~ElaStatusBarStyle() override = default;

    void drawPrimitive(PrimitiveElement element, const QStyleOption* option, QPainter* painter, const QWidget* widget = nullptr) const override
    {
        switch (element)
        {
        case QStyle::PE_PanelStatusBar:
        {
            //背景绘制
            QRect statusBarRect = option->rect;
            painter->save();
            painter->setRenderHints(QPainter::Antialiasing | QPainter::TextAntialiasing);
            painter->setPen(ElaThemeColor(_themeMode, BasicBorder));
            painter->setBrush(ElaThemeColor(_themeMode, BasicBaseAlpha));
            painter->drawRect(statusBarRect);
            painter->restore();
            return;
        }
        case QStyle::PE_FrameStatusBarItem:
        {
            //间隔符绘制
            const auto* statusBar = dynamic_cast<const QStatusBar*>(widget->parentWidget());
            if (statusBar && statusBar->isSizeGripEnabled())
            {
                QRect statusBarItemRect = option->rect;
                painter->save();
                painter->setRenderHints(QPainter::Antialiasing | QPainter::TextAntialiasing);
                painter->setPen(Qt::NoPen);
                painter->setBrush(ElaThemeColor(_themeMode, PrimaryNormal));
                painter->drawRoundedRect(
                    QRectF(
                        statusBarItemRect.right() - 3,
                        statusBarItemRect.y() + statusBarItemRect.height() * 0.1,
                        3,
                        statusBarItemRect.height() - statusBarItemRect.height() * 0.2
                    ),
                    2,
                    2
                );
                painter->restore();
            }
            return;
        }
        default:
        {
            break;
        }
        }
        QProxyStyle::drawPrimitive(element, option, painter, widget);
    }

    void drawControl(ControlElement element, const QStyleOption* option, QPainter* painter, const QWidget* widget = nullptr) const override
    {
        switch (element)
        {
        case QStyle::CE_SizeGrip:
        {
            return;
        }
        default:
        {
            break;
        }
        }

        QProxyStyle::drawControl(element, option, painter, widget);
    }

    QSize sizeFromContents(ContentsType type, const QStyleOption* option, const QSize& size, const QWidget* widget) const override
    {
        //qDebug() << type << QProxyStyle::sizeFromContents(type, option, size, widget);
        return QProxyStyle::sizeFromContents(type, option, size, widget);
    }

    int pixelMetric(PixelMetric metric, const QStyleOption* option = nullptr, const QWidget* widget = nullptr) const override
    {
        return QProxyStyle::pixelMetric(metric, option, widget);
    }

private:
    ElaThemeType::ThemeMode _themeMode{ElaThemeType::Light};
};

