        _basicColorView->setModel(_basicColorModel);
        _basicColorDelegate = new ElaColorDisplayDelegate(this);
        _basicColorView->setItemDelegate(_basicColorDelegate);
        _initBasicColor();
        connect(_basicColorView, &ElaBaseListView::clicked, this, &ElaColorDialog::onBasicColorViewClicked);

        auto* basicColorViewText = new ElaText("基本颜色", this);
        basicColorViewText->setTextPixelSize(14);
        auto* basicColorLayout = new QVBoxLayout();
        basicColorLayout->setContentsMargins(3, 0, 0, 0);
