        _customColorView->setModel(_customColorModel);
        _customColorDelegate = new ElaColorDisplayDelegate(this);
        _customColorView->setItemDelegate(_customColorDelegate);
        _initCustomColor();
        connect(_customColorView, &ElaBaseListView::clicked, this, &ElaColorDialog::onCustomColorViewClicked);

        // 增加移除按钮
        _addCustomColorButton = new ElaToolButton(this);
        _addCustomColorButton->setIsTransparent(false);
        _addCustomColorButton->setElaIcon(ElaIconType::Plus);
        connect(_addCustomColorButton, &ElaToolButton::clicked, this, &ElaColorDialog::onAddCustomColorButtonClicked);

        _removeCustomColorButton = new ElaToolButton(this);
        _removeCustomColorButton->setIsTransparent(false);
        _removeCustomColorButton->setElaIcon(ElaIconType::Minus);
        connect(_removeCustomColorButton, &ElaToolButton::clicked, this, &ElaColorDialog::onRemoveCustomColorButtonClicked);

        auto* customColorViewText = new ElaText("自定义颜色", this);
        customColorViewText->setTextPixelSize(14);
