    void setNavigationBarDisplayMode(ElaNavigationType::NavigationDisplayMode navigationBarDisplayMode)
    {
        _pNavigationBarDisplayMode = navigationBarDisplayMode;
        _currentNavigationBarDisplayMode = _pNavigationBarDisplayMode;
        bool isVisible = this->isVisible();
        switch (_pNavigationBarDisplayMode)
        {
        case ElaNavigationType::Auto:
        {
            _doNavigationDisplayModeChange();
            break;
        }
        case ElaNavigationType::Minimal:
        {
            _navigationBar->setDisplayMode(ElaNavigationType::Minimal, isVisible);
            break;
        }
        case ElaNavigationType::Compact:
        {
            _navigationBar->setDisplayMode(ElaNavigationType::Compact, isVisible);
            break;
        }
        case ElaNavigationType::Maximal:
        {
            _navigationBar->setDisplayMode(ElaNavigationType::Maximal, isVisible);
            break;
        }
        }
        Q_EMIT pNavigationBarDisplayModeChanged();
    }

