    void backtrackNavigationNode(const QString& nodeKey)
    {
        const QMetaObject* meta = _pageMetaMap.value(nodeKey);
        if (!meta)
        {
            return;
        }
        if (auto* widget = dynamic_cast<QWidget*>(meta->newInstance()))
        {
            auto originWidget = _routeMap[nodeKey];
            int currentIndex = _navigationCenterStackedWidget->getContainerStackedWidget()->currentIndex();
            int originIndex = _navigationCenterStackedWidget->getContainerStackedWidget()->indexOf(originWidget);
            widget->setProperty("ElaPageKey", nodeKey);
            _routeMap[nodeKey] = widget;
            _navigationCenterStackedWidget->getContainerStackedWidget()->insertWidget(originIndex, widget);
            _navigationCenterStackedWidget->getContainerStackedWidget()->setCurrentIndex(currentIndex);
            _navigationCenterStackedWidget->getContainerStackedWidget()->removeWidget(originWidget);
            originWidget->deleteLater();
        }
    }


